# python
from collections import deque
from openpyxl import load_workbook
from openpyxl.utils import column_index_from_string

fp = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx'
wb = load_workbook(fp)
ws = wb.active

def rgb(argb):
    return argb[-6:].upper() if argb else None

def is_blue(h):
    if not h:
        return False
    r = int(h[0:2],16); g=int(h[2:4],16); b=int(h[4:6],16)
    return b>200 and r<80 and g<180

def coord_to_idx(c):
    i=0
    while i<len(c) and not c[i].isdigit():
        i+=1
    col = column_index_from_string(c[:i])
    row = int(c[i:])
    return (row,col)

blue = set()
colors = {}
for row in ws.iter_rows():
    for cell in row:
        h = None
        if cell.fill and cell.fill.fgColor and cell.fill.fgColor.type=='rgb' and cell.fill.fgColor.rgb:
            h = rgb(cell.fill.fgColor.rgb)
        idx = coord_to_idx(cell.coordinate)
        colors[idx] = h
        if is_blue(h):
            blue.add(idx)

start=(1,1)
max_row=20; max_col=9
D={'up':(-2,0),'down':(2,0),'left':(0,-2),'right':(0,2)}
q=deque([(start[0],start[1],0,None)])
seen=set()
found=None
while q:
    r,c,m,p = q.popleft()
    if m==11:
        found=(r,c)
        break
    for dn,(dr,dc) in D.items():
        if p and ((p=='up' and dn=='down') or (p=='down' and dn=='up') or (p=='left' and dn=='right') or (p=='right' and dn=='left')):
            continue
        nr=r+dr; nc=c+dc
        if 1<=nr<=max_row and 1<=nc<=max_col and (nr,nc) not in blue:
            st=(nr,nc,m+1,dn)
            if st not in seen:
                seen.add(st)
                q.append(st)

print('Found 11th position:', found)
print('Color at 11th:', colors.get(found))
